sect3.para:
public class Gun { private final int maxBullets; private int bullets; public Gun(int maxBullets) {
    this.maxBullets = maxBullets;
}

public int getMaxBullets() {
    return maxBullets;
}

public int reload(int bullets) {
    if (bullets < 0) {
        System.out.println("Не может быть отрицательного числа патронов.");
        return 0;
    }

    if (bullets > maxBullets) {
        this.bullets = maxBullets;
        return bullets - maxBullets;
    }

    this.bullets = bullets;

    return 0;
}

public int unload() {
    int returnBullets = this.bullets;
    this.bullets = 0;
    return returnBullets;
}

public int getBullets() {
    return ammo;
}

public boolean isLoaded() {
    return ammo > 0;
}

public void fire() {
    if (bullets > 0) {
        bullets--;
        System.out.println("Бах!");
    } else {
        System.out.println("Клац!");
    }
}

@Override
public String toString() {
    return ("Пистолет с максимумом " + maxBullets + " патронов, заряженный на " + bullets + " пуль.");
}
 }

public final class Names { private final String lastName; private final String firstName; private final String patronymic; public Names(String firstName) {
    if (firstName == null || firstName.trim().isEmpty()) {
        throw new IllegalArgumentException("Имя не может быть пустым");
    }
    this.firstName = firstName;
    this.lastName = null;
    this.patronymic = null;
}

public Names(String firstName, String lastName) {
    if ((firstName == null || firstName.trim().isEmpty()) &&
            (lastName == null || lastName.trim().isEmpty())) {
        throw new IllegalArgumentException("Хотя бы один параметр должен быть заполнен");
    }
    this.firstName = firstName;
    this.lastName = lastName;
    this.patronymic = null;
}

public Names(String firstName, String lastName, String patronymic) {
    if ((firstName == null || firstName.trim().isEmpty()) &&
            (lastName == null || lastName.trim().isEmpty()) &&
            (patronymic == null || patronymic.trim().isEmpty())) {
        throw new IllegalArgumentException("Хотя бы один параметр должен быть заполнен");
    }
    this.firstName = firstName;
    this.lastName = lastName;
    this.patronymic = patronymic;
}

@Override
public String toString() {
    String result = firstName;
    if (lastName != null && !lastName.isEmpty()) {
        result += " " + lastName;
    }
    if (patronymic != null && !patronymic.isEmpty()) {
        result += " " + patronymic;
    }
    return result;
}
 }

public class PhoneBook { private Map<String, String> contacts; public PhoneBook() {
    this.contacts = new HashMap<>();
}

public String addContact(String phoneNumber, String name) {
    String previousNumber = null;

    for (Map.Entry<String, String> entry: contacts.entrySet()) {
        if (entry.getValue().equals(name)) {
            previousNumber = entry.getKey();
            contacts.remove(previousNumber);
        }
    }

    contacts.put(phoneNumber, name);

    return previousNumber;
}

public void removeContact(String name) {
    for (Map.Entry<String, String> entry : contacts.entrySet()) {
        if (entry.getValue().equals(name)) {
            contacts.remove(entry.getKey());
        }
    }
}

public String getContact(String name) {
    for (Map.Entry<String, String> entry : contacts.entrySet()) {
        if (entry.getValue().equals(name)) {
            return entry.getKey() + " - " + entry.getValue();
        }
    }

    return "Не найдено";
}

public String checkContact(String text) {
    for (Map.Entry<String, String> entry : contacts.entrySet()) {
        if (entry.getValue().equals(text) || entry.getKey().equals(text)) {
            return entry.getKey() + " - " + entry.getValue();
        }
    }

    return "Не существует";
}

public int countContact() {
    int count = 0;

    for (Map.Entry<String, String> entry : contacts.entrySet()) {
        count++;
    }

    return count;
}

public String[] getContactArray(int choice) {
    String[] contactsArray = new String[contacts.size()];
    int i = 0;

    switch (choice) {
        case 1:
            for (Map.Entry<String, String> entry : contacts.entrySet()) {
                contactsArray[i] = entry.getKey() + " - " + entry.getValue();
                i++;
            }
            break;
        case 2:
            for (Map.Entry<String, String> entry : contacts.entrySet()) {
                contactsArray[i] = entry.getKey();
                i++;
            }
            break;
        case 3:
            for (Map.Entry<String, String> entry : contacts.entrySet()) {
                contactsArray[i] = entry.getValue();
                i++;
            }
            break;
        default:
            return contactsArray;
    }
    return contactsArray;
}

public String[] contactSearch(String namePart) {
    String[] foundContacts = new String[contacts.size()];
    int i = 0;
    String name;

    for (Map.Entry<String, String> entry : contacts.entrySet()) {
        name = entry.getValue();
        if (name.startsWith(namePart)) {
            foundContacts[i] = entry.getValue();
            i++;
        }
    }

    return foundContacts;
}

@Override
public String toString() {
    String result = "";
    for (Map.Entry<String, String> entry : contacts.entrySet()) {
        result = result + entry.getKey() + " - " + entry.getValue() + "; ";
    }
    return result;
}

public class Automate extends Gun{ private final int speed; public Automate() {
    this.speed = 30;
}

public Automate(int maxBullets) {
    super(maxBullets);
    this.speed = maxBullets / 2;
}

public Automate(int maxBullets, int speed) {
    super(maxBullets);
    this.speed = speed;
}

@Override
public void fire() {
    for (int i = 0; i < speed; i++) {
        super.fire();
    }
}

public void longFire(int time) {
    for (int i = 0; i < (time * speed); i++) {
        super.fire();
    }
}
 }

para.verbatim:
    public Gun() {
        super(0);
        this.maxBullets = 30;
    }

    public Gun(int maxBullets) {
        super(0);
        this.maxBullets = maxBullets;
    }

    public int getMaxBullets () {
        return maxBullets;
    }

    @Override
    public void shoot() {
        if (getAmmo()) {
            System.out.println("Бах!");
        } else {
            System.out.println("Клац!");
        }
    }

    @Override
    public int load(int ammo) {
        if (ammo < 0) {
            System.out.println("Не может быть отрицательного числа патронов.");
            return 0;
        }

        if (ammo > maxBullets) {
            super.load(maxBullets);
            return ammo - maxBullets;
        }

        super.load(ammo);

        return 0;
    }

    public int unload () {
        int returnBullets = ammo();
        load(0);
        return returnBullets;
    }

    public int getBullets() {
        return ammo;
    }

    public boolean isLoaded() {
        return ammo > 0;
    }

    @Override
    public String toString() {
        return ("Пистолет с максимумом " + maxBullets + " патронов, заряженный на " + ammo() + " пуль.");
    }
}

sect3.para:
public class Shooter { private String name; private Weapon weapon; public Shooter(String name) {
    this.name = name;
}

public void setName(String name) {
    this.name = name;
}

public void setWeapon(Weapon weapon) {
    this.weapon = weapon;
}

public void shoot() {
    if (this.weapon != null) {
        weapon.shoot();
    } else {
        System.out.println("не могу участвовать в перестрелке");
    }
}
 }

abstract class Weapon { protected int ammo; public Weapon(int ammo) {
    if(ammo<0) throw new RuntimeException();
    this.ammo = ammo;
}
public abstract void shoot();
public int ammo() {return ammo;}
public boolean getAmmo() {
    if(ammo==0) return false;
    ammo--;
    return true;
}

public int load(int ammo) {
    if(ammo<0) throw new RuntimeException();
    int tmp=ammo;
    this.ammo=ammo;
    return tmp;
}
 }
